function renderProduct(p) {
  let imgHTML = '';
  if (p.placeholder) {
    imgHTML = `<div style="display: flex; flex-direction: column; align-items: center; justify-content: center; color: white; gap: 6px; padding: 20px;"><div style="font-size: 56px; font-weight: 800; color: white; line-height: 1; letter-spacing: -0.04em;">${p.placeholder.num}</div><div style="font-size: 9px; font-weight: 700; color: var(--gold-bright); letter-spacing: 0.18em; text-transform: uppercase;">${p.placeholder.tag}</div></div>`;
  } else if (p.isUrl) {
    imgHTML = `<img src="${p.img}" alt="${p.title}" loading="lazy">`;
  } else {
    imgHTML = `<img src="data:image/jpeg;base64,${p.img}" alt="${p.title}" loading="lazy">`;
  }

  let priceHTML = '';
  if (typeof p.price === 'number') {
    priceHTML = `<div class="product-price-row"><span class="product-price">$${p.price.toLocaleString()}</span>${p.oldPrice ? `<span class="product-price-old">$${p.oldPrice.toLocaleString()}</span>` : ''}${p.save ? `<span class="product-price-save">−${p.save}%</span>` : ''}</div>`;
  } else {
    priceHTML = `<div class="product-price-row"><span class="product-price" style="color: var(--coral-deep);">${p.price}</span></div>`;
  }

  let shippingHTML = '';
  if (p.shipping === 'free') {
    shippingHTML = `<div class="product-shipping"><span class="free">Free shipping</span> · arrives in 2 days</div>`;
  } else if (p.shipping === 'concierge') {
    shippingHTML = `<div class="product-shipping">Concierge delivery · contact for details</div>`;
  }

  const ratingStars = Math.floor(p.rating || 0);
  let starsHTML = '';
  for (let i = 0; i < 5; i++) {
    starsHTML += i < ratingStars ? '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>' : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>';
  }
  const ratingHTML = p.rating ? `<div class="product-rating"><div class="stars">${starsHTML}</div><strong>${p.rating}</strong><span>(${p.reviews})</span></div>` : '';
  const badgesHTML = (p.badges || []).map(b => `<span class="product-badge ${b.cls}">${b.text}</span>`).join('');
  const stockClass = p.stockLow ? 'stock low' : 'stock';

  return `<a href="${window.AZ_HOME || '/'}product/?item=${p.id}" class="product"><div class="product-img ${p.imgClass||''}">${badgesHTML}<button class="wishlist-btn" onclick="event.preventDefault(); event.stopPropagation(); this.classList.toggle('active');" aria-label="Save to wishlist"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg></button>${imgHTML}</div><div class="product-body"><div class="product-cat">${p.cat}</div><div class="product-title">${p.title}</div>${ratingHTML}${priceHTML}${shippingHTML}<div class="product-meta-row"><span class="product-meta-pill ${stockClass}">${p.stock}</span><span class="product-meta-pill seller"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M9 12l2 2 4-4 5 5-9 9-9-9 5-5 2 2z"/></svg>${p.seller}</span></div></div></a>`;
}

